INSERT INTO `customer_reviews` VALUES (1,'Rian Hidayat','Mahasiswa Rantau (Bandung) - Universitas Diponegoro',5,'Sebagai mahasiswa rantau dari Bandung, tinggal di Asri Boarding House bener-bener membantu banget. Kamarnya nyaman dan luas buat belajar, internetnya super kencang tanpa putus buat ngerjain tugas kuliah, dan deket banget ke kampus UNDIP. Suasana lingkungannya juga tenang dan aman!',NULL,'2026-08-28 07:32:06','2026-08-28 07:32:06'),(2,'Amelia Putri','Pekerja Kantoran (Jakarta) - IT Consultant Semarang',5,'Sangat cocok untuk pekerja rantau yang butuh ketenangan setelah seharian kerja. Fasilitas AC-nya dingin, kamar mandi bersih di dalam, dan yang paling penting listriknya sudah include (tidak perlu pusing beli token lagi). Akses ke pusat kota juga gampang sekali.',NULL,'2026-08-28 07:32:06','2026-08-28 07:32:06'),(3,'Bagas Saputra','Mahasiswa Rantau (Surabaya) - Polines',5,'Sudah hampir 2 tahun ngekost di sini. Kamarnya bersih, ada fasilitas cleaning service mingguan, dan pengelolanya sangat ramah serta responsif kalau ada kendala fasilitas. Dekat dengan warung makan dan minimarket, jadi gampang cari kebutuhan sehari-hari.',NULL,'2026-08-28 07:32:06','2026-08-28 07:32:06');
/*!40000 ALTER TABLE `customer_reviews` ENABLE KEYS */;
UNLOCK TABLES;

