/*!40000 ALTER TABLE `faqs` DISABLE KEYS */;
INSERT INTO `faqs` VALUES (1,'Bagaimana cara memesan kamar di Asri Boarding House? Apakah bisa online?','Sangat mudah dan praktis! Anda bisa memesan kamar impian 100% online secara aman. Cukup pilih kamar yang Anda suka di halaman Katalog Kamar, klik \"Pesan Unit\", isi formulir data diri singkat, lalu selesaikan pembayaran Uang Muka (DP minimal 30%) atau pelunasan langsung secara online melalui virtual account, QRIS/e-wallet, atau kartu kredit via Midtrans.',1,1,'2026-08-28 07:32:06','2026-08-28 07:32:06'),(2,'Apakah harga sewa bulanan sudah termasuk biaya listrik dan air?','Benar sekali! Seluruh biaya sewa kamar di Asri Boarding House sudah bersifat All-In, yaitu sudah mencakup gratis listrik harian dan pemakaian air bersih. Anda tidak perlu lagi khawatir dengan tagihan tambahan atau pusing memikirkan token listrik bulanan!',2,1,'2026-08-28 07:32:06','2026-08-28 07:32:06'),(3,'Fasilitas eksklusif apa saja yang sudah siap saya gunakan di dalam kamar?','Kamar kami siap huni (ready-to-use) dengan fasilitas premium: AC dingin, kamar mandi dalam bersih & modern, kasur spring bed premium yang empuk, meja & kursi belajar nyaman, lemari pakaian fungsional, sirkulasi udara optimal dengan jendela luar, serta koneksi Wi-Fi super cepat 24 jam.',3,1,'2026-08-28 07:32:06','2026-08-28 07:32:06'),(4,'Bagaimana dengan sistem akses gerbang? Apakah ada jam malam?','Demi menunjang produktivitas Anda, kami memberikan akses bebas penuh 24 jam. Pintu masuk area kost menggunakan sistem keamanan mandiri (smart access gate & digital lock), sehingga Anda bebas pulang-pergi dengan aman sesuai kesibukan kuliah/kerja tanpa perlu cemas terkunci di luar.',4,1,'2026-08-28 07:32:06','2026-08-28 07:32:06'),(5,'Bagaimana cara membayar tagihan sewa untuk bulan-bulan berikutnya?','Pembayaran sangat transparan dan otomatis. Anda cukup masuk ke Portal Penyewa, buka menu \"Tagihan Saya\", dan selesaikan pembayaran secara instan menggunakan metode online (Virtual Account bank pilihan, ShopeePay/GoPay/OVO/Dana, QRIS, atau gerai ritel). Sistem kami akan langsung mencatat pembayaran Anda dalam hitungan detik secara otomatis.',5,1,'2026-08-28 07:32:06','2026-08-28 07:32:06');
/*!40000 ALTER TABLE `faqs` ENABLE KEYS */;
UNLOCK TABLES;

