INSERT INTO `fasilitas` VALUES (25,'Air Conditioner (AC)','snowflake','Pendingin ruangan untuk kenyamanan maksimal sepanjang hari.',1,'2026-08-28 07:31:34',NULL),(26,'Wi-Fi High Speed','wifi','Koneksi internet nirkabel cepat dan stabil di seluruh area kamar.',1,'2026-08-28 07:31:34',NULL),(27,'Free Listrik','bolt','Biaya sewa sudah termasuk penggunaan listrik standar.',1,'2026-08-28 07:31:34',NULL),(28,'Kamar Mandi Dalam','bath','Kamar mandi pribadi di dalam kamar dilengkapi fasilitas saniter modern.',1,'2026-08-28 07:31:34',NULL),(29,'Kamar Mandi Luar (Bersama)','shower','Kamar mandi luar bersih untuk digunakan bersama.',1,'2026-08-28 07:31:34',NULL),(30,'Lemari Pakaian','door-closed','Lemari pakaian luas untuk penyimpanan pakaian.',1,'2026-08-28 07:31:34',NULL),(31,'Meja Belajar','desktop','Meja belajar/kerja minimalis dengan kursi nyaman.',1,'2026-08-28 07:31:34',NULL),(32,'Kasur Springbed Queen','bed','Kasur berkualitas tinggi untuk istirahat tidur yang nyaman.',1,'2026-08-28 07:31:34',NULL);
