INSERT INTO `galleries` VALUES (3,'Kamar VIP Eksklusif','Desain interior mewah dengan tempat tidur queen size, AC, smart TV, kamar mandi dalam, dan meja kerja modern.','https://images.unsplash.com/photo-1618773928121-c32242e63f39?auto=format&fit=crop&w=800&q=80',1,1,'2026-08-28 07:32:06','2026-08-28 07:32:06'),(4,'Kamar Deluxe Nyaman','Kamar luas dengan pencahayaan alami yang baik, dilengkapi dengan AC, kamar mandi dalam, lemari pakaian, dan meja belajar.','https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&w=800&q=80',2,1,'2026-08-28 07:32:06','2026-08-28 07:32:06'),(5,'Kamar Standar Fungsional','Hunian kost yang praktis dan efisien dengan kasur single, AC, meja belajar, lemari, sirkulasi udara optimal, dan kamar mandi dalam.','https://images.unsplash.com/photo-1598928506311-c55ded91a20c?auto=format&fit=crop&w=800&q=80',3,1,'2026-08-28 07:32:06','2026-08-28 07:32:06');
