INSERT INTO `peraturan` VALUES (1,'Kebersihan & Kerapian','Selalu menjaga kebersihan, kerapian, dan ketertiban di lingkungan bersama Asri Boarding House.','sparkles',1,'2026-08-28 07:32:06','2026-08-28 07:32:06'),(2,'Penggunaan Energi','Apabila meninggalkan kamar kost, wajib mematikan AC, lampu, serta seluruh peralatan elektronik lainnya.','bolt',2,'2026-08-28 07:32:06','2026-08-28 07:32:06'),(3,'Elektronik Tambahan','Wajib melaporkan dengan jujur kepada pengelola kost apabila membawa dan menggunakan barang elektronik tambahan di luar fasilitas standar.','computer-desktop',3,'2026-08-28 07:32:06','2026-08-28 07:32:06'),(4,'Siklus Pembayaran','Pembayaran uang sewa kost wajib dilakukan tepat waktu di awal bulan, paling lambat sebelum tanggal 10. Jika terjadi keterlambatan, penyewa wajib segera melakukan konfirmasi kepada pengelola.','credit-card',4,'2026-08-28 07:32:06','2026-08-28 07:32:06'),(5,'Disiplin Saluran Pembuangan','Dilarang keras membuang pembalut wanita, tisu, sisa makanan, atau benda apa pun ke dalam kloset dan saluran pembuangan kamar mandi.','exclamation-triangle',5,'2026-08-28 07:32:06','2026-08-28 07:32:06'),(6,'Ketentuan Tamu Menginap','Tamu yang menginap lebih dari 24 jam wajib melapor kepada pengelola kost. Apabila tamu menginap lebih dari 3 malam, akan dikenakan biaya tambahan sesuai ketentuan.','user-group',6,'2026-08-28 07:32:06','2026-08-28 07:32:06'),(7,'Aturan Tamu Pria','Tamu pria dilarang keras masuk ke dalam kamar maupun area dalam kost putri. Menerima tamu pria hanya diizinkan di ruang tamu utama yang telah disediakan, kecuali atas izin khusus pengelola.','shield-alert',7,'2026-08-28 07:32:06','2026-08-28 07:32:06'),(8,'Larangan Merokok','Dilarang keras merokok di dalam seluruh area lantai 1, lantai 2, maupun lingkungan dalam kawasan kost putri.','no-symbol',8,'2026-08-28 07:32:06','2026-08-28 07:32:06'),(9,'Jam Malam & Akses Gerbang','Batas jam malam bertamu maksimal pukul 22:00 WIB. Bagi penghuni yang pulang ke kost di atas pukul 22:00 WIB, wajib memberikan laporan atau izin terlebih dahulu kepada pengelola/penjaga kost.','moon',9,'2026-08-28 07:32:06','2026-08-28 07:32:06');
/*!40000 ALTER TABLE `peraturan` ENABLE KEYS */;
UNLOCK TABLES;

